arguments.argument:
open=get_open_filename("cei파일을 선택해주세요|*.cei", "")

if open!=""
{
var vb_file, vb_read;

vb_file=file_bin_open(open, 0)

file_bin_seek(vb_file, 5080)
repeat(4){max_h=sk_hex_conversion(file_bin_read_byte(vb_file))+max_h}
max_d=sk_dec_conversion(max_h)
//이동그림 최대값

for(i=0; i!=8; i+=1)
{
file_bin_seek(vb_file, 972+(i*512))

for(j=0; j!=max_d; j+=1)
{
up[i, j]=0; down[i, j]=0; left[i, j]=0; right[i, j]=0

vb_read=""
repeat(4){vb_read=sk_hex_conversion(file_bin_read_byte(vb_file))+vb_read}

if string_delete(vb_read, 3, string_length(vb_read))="FF"{left[i, j]=256-sk_dec_conversion(string_delete(vb_read, 1, 6))}
else{right[i, j]=sk_dec_conversion(string_delete(vb_read, 1, 6))}
//홀수

vb_read=""
repeat(4){vb_read=sk_hex_conversion(file_bin_read_byte(vb_file))+vb_read}

if string_delete(vb_read, 3, string_length(vb_read))="FF"{up[i, j]=256-sk_dec_conversion(string_delete(vb_read, 1, 6))}
else{down[i, j]=sk_dec_conversion(string_delete(vb_read, 1, 6))}
//짝수
}

}

file_bin_close(vb_file)
}
else
{
game_end()
}
